import Link from "next/link";
import { Lock, FileText, Calendar, User, Download } from "lucide-react";
import {
  listArchivedMatters,
  listPendingArchiveRecords
} from "@/server/archive/actions";
import { CLOSED_REASON_LABEL } from "@/server/archive/schemas";
import { Badge } from "@/components/ui/badge";
import { requireSession } from "@/lib/auth/session";
import { PendingArchiveTable } from "./_components/pending-archive-table";
import { ArchiveTabs } from "./_components/archive-tabs";
import { ArchiveExplorer } from "./_components/archive-explorer";
import { matterHref } from "@/lib/matters/route";

const CATEGORY_LABEL: Record<string, string> = {
  CIVIL_COMMERCIAL: "Civil/Comercial",
  CRIMINAL: "Penal",
  ADMINISTRATIVE: "Administrativo",
  NON_LITIGATION: "No contencioso",
  LEGAL_COUNSEL: "Consultoría",
  SPECIAL_PROJECT: "Proyecto especial",
  LABOR_ARBITRATION: "Arbitraje laboral",
  COMMERCIAL_ARBITRATION: "Arbitraje comercial",
};

export default async function ArchivePage({
  searchParams
}: {
  searchParams?: Promise<{ tab?: string }>;
}) {
  const session = await requireSession();
  const isAdmin = session.user.role === "ADMIN";
  const params = (await searchParams) ?? {};
  const tab = params.tab ?? "approved";
  const activeTab = isAdmin && tab === "pending" ? "pending" : tab === "explorer" ? "explorer" : "approved";

  const [items, pending] = await Promise.all([
    activeTab === "explorer" ? [] : listArchivedMatters(),
    isAdmin ? listPendingArchiveRecords() : Promise.resolve([])
  ]);

  return (
    <div className="px-6 py-6 space-y-5">
      <header className="flex items-end justify-between">
        <div>
          <h1 className="text-xl font-medium flex items-center gap-2">
            <Lock className="h-5 w-5 text-[#9B7BF7]" />
            Gestión de archivo
          </h1>
          <p className="text-xs text-muted-foreground mt-1">
            {activeTab === "explorer"
              ? "Explorá las carpetas de casos archivados, seleccioná y descargá documentos."
              : isAdmin
                ? "Vista de administrador: aprobación de solicitudes pendientes de archivo + ver casos archivados."
                : "Los casos archivados se ordenan por fecha de archivo descendente."}
          </p>
        </div>
        <span className="text-xs text-muted-foreground">
          {activeTab === "pending"
            ? `Pendientes de aprobación ${pending.length} casos`
            : activeTab === "explorer"
              ? "Explorador de carpetas"
              : `Archivados ${items.length} casos`}
        </span>
      </header>

      {isAdmin && (
        <ArchiveTabs active={activeTab} pendingCount={pending.length} />
      )}

      {activeTab === "pending" && isAdmin ? (
        <PendingArchiveTable records={pending as any} />
      ) : activeTab === "explorer" ? (
        <ArchiveExplorer />
      ) : items.length === 0 ? (
        <div className="rounded-lg border border-dashed border-border/60 py-16 text-center text-sm text-muted-foreground">
          No hay casos archivados.
        </div>
      ) : (
        <div className="rounded-lg border border-border/60 overflow-hidden">
          <table className="w-full text-sm">
            <thead className="bg-muted/30 text-xs text-muted-foreground">
              <tr>
                <th className="px-3 py-2 text-left font-normal w-32">N° interno</th>
                <th className="px-3 py-2 text-left font-normal">Caso</th>
                <th className="px-3 py-2 text-left font-normal w-20">Categoría</th>
                <th className="px-3 py-2 text-left font-normal w-24">Cliente</th>
                <th className="px-3 py-2 text-left font-normal w-20">Modo de cierre</th>
                <th className="px-3 py-2 text-left font-normal w-28">Fecha de cierre</th>
                <th className="px-3 py-2 text-left font-normal w-28">Fecha de archivo</th>
                <th className="px-3 py-2 text-left font-normal w-20">Archivado por</th>
                <th className="px-3 py-2 text-left font-normal w-16">Faltantes</th>
                <th className="px-3 py-2 text-left font-normal w-16">Exportar</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {items.map((rec) => (
                <tr key={rec.id} className="hover:bg-muted/20 transition-colors">
                  <td className="px-3 py-2.5 font-mono text-xs text-[#9B7BF7]">
                    {rec.matter.firmCaseNo ?? "—"}
                  </td>
                  <td className="px-3 py-2.5">
                    <Link
                      href={matterHref(rec.matter)}
                      className="hover:text-[#5B8DEF] transition-colors line-clamp-1"
                    >
                      <FileText className="h-3 w-3 inline mr-1 text-muted-foreground" />
                      {rec.matter.title}
                    </Link>
                  </td>
                  <td className="px-3 py-2.5 text-xs">
                    {CATEGORY_LABEL[rec.matter.category] ?? rec.matter.category}
                  </td>
                  <td className="px-3 py-2.5 text-xs">
                    <User className="h-3 w-3 inline mr-1 text-muted-foreground" />
                    {rec.matter.primaryClient?.name ?? "—"}
                  </td>
                  <td className="px-3 py-2.5 text-xs">
                    {rec.closedReason ? CLOSED_REASON_LABEL[rec.closedReason] : "—"}
                  </td>
                  <td className="px-3 py-2.5 text-xs text-muted-foreground">
                    <Calendar className="h-3 w-3 inline mr-1" />
                    {rec.completedAt ? rec.completedAt.toISOString().slice(0, 10) : "—"}
                  </td>
                  <td className="px-3 py-2.5 text-xs text-muted-foreground">
                    {rec.archivedAt.toISOString().slice(0, 10)}
                  </td>
                  <td className="px-3 py-2.5 text-xs">{rec.archivedBy}</td>
                  <td className="px-3 py-2.5">
                    {(rec.missingItems as string[]).length > 0 ? (
                      <Badge variant="outline" className="border-amber-500/40 text-amber-400 text-[10px]">
                        {(rec.missingItems as string[]).length} ítems
                      </Badge>
                    ) : (
                      <span className="text-xs text-muted-foreground">Completo</span>
                    )}
                  </td>
                  <td className="px-3 py-2.5">
                    <a
                      href={`/api/archive/${rec.matter.id}/export`}
                      className="inline-flex items-center gap-1 text-xs text-[#5B8DEF] hover:text-[#5B8DEF]/80"
                      title="Exportar ZIP de archivo"
                    >
                      <Download className="h-3 w-3" />
                      ZIP
                    </a>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
